<?php require "db.php"; if ($_SERVER["REQUEST_METHOD"] !== "POST") { header("Location: register.html"); exit; } $username = trim($_POST["username"] ?? ""); $email = trim($_POST["email"] ?? ""); $password = $_POST["password"] ?? ""; $confirmPassword = $_POST["confirm_password"] ?? ""; /* * Basic validation */ if ($username === "" || $email === "" || $password === "") { die("Please complete all fields."); } if (!filter_var($email, FILTER_VALIDATE_EMAIL)) { die("Please enter a valid email address."); } if (strlen($username) < 3 || strlen($username) > 50) { die("Username must be between 3 and 50 characters."); } if (strlen($password) < 8) { die("Password must be at least 8 characters."); } if ($password !== $confirmPassword) { die("Passwords do not match."); } /* * Check whether username or email already exists */ $stmt = $pdo->prepare( "SELECT id FROM users WHERE username = ? OR email = ? LIMIT 1" ); $stmt->execute([ $username, $email ]); if ($stmt->fetch()) { die("Username or email is already registered."); } /* * Hash the password */ $passwordHash = password_hash( $password, PASSWORD_DEFAULT ); /* * Create the user */ $stmt = $pdo->prepare( "INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)" ); $stmt->execute([ $username, $email, $passwordHash ]); /* * Registration successful */ header("Location: index.html"); exit; ?>